const db = $input.first().json;
const called = $('Called With checkin_id').first().json;

const type = String(called.notification_type ?? 'interaction');
const mode = String(db.notify_mode ?? 'every_time');

// Architecture 8 / WF-6: the OWNING ROUTINE's notify_care_partner is
// authoritative. domain_configs.ct_notification is derived/deprecated (A-9).
// not_required = total silence: no confirmation and no missed push. The miss
// is still recorded in the DB and visible on the dashboard.
let shouldSend = false;
if (mode !== 'not_required') {
  if (type === 'missed') {
    shouldSend = true;
  } else if (mode === 'every_time') {
    shouldSend = true;
  } else if (mode === 'only_missed' && db.response_value === 'some_of_them') {
    // Ruled by Talal 3 Aug 2026: a partial dose is closer to a miss than to a
    // clean yes, so only_missed still notifies. Deliberate deviation from the
    // literal reading of only_missed - do not 'fix' it back.
    shouldSend = true;
  }
}

// Medication aggregates several medicines into one slot, so it has no single
// routine name and uses the derived period label. Food and health are 1:1 with
// their routine, so the CT sees the name she actually typed - Dinner, BP check.
let missedLabel;
let interactionLabel;
if (db.domain === 'medication') {
  missedLabel = db.period_label + ' Medication';
  interactionLabel = 'Medication (' + db.period_label + ')';
} else {
  const name = String(db.routine_name || db.domain);
  missedLabel = name;
  interactionLabel = name + ' (' + db.period_label + ')';
}

return [{ json: Object.assign({}, db, { notification_type: type, should_send: shouldSend, is_missed: type === 'missed', routine_label_missed: missedLabel, routine_label_interaction: interactionLabel }) }];
